# data/maps/farm.map - "Min Trækronsgård" (the player's treetop farm). PROTOTYPE of design3 track N (generated by gen_farm_map.py).
# Orientation (layout DIAMOND_DOWN): text COLUMNS run toward screen lower-RIGHT (+x), text ROWS toward screen lower-LEFT (+y);
# top-left char = NORTH corner, top-right = EAST, bottom-right = SOUTH, bottom-left = WEST.
# The farmhouse stands against the great trunk at the north-east rim; its door cell carries marker H (home). Reserve (tier 10 = 9 x 6):
# base deck x D-4..D+4, y D-2..D, growth rows y D-3 / D-4 / D-5 are VOID here and turn into deck with set_growth_stage(1..3).
@id farm
@title ZONE_FARM
@projection iso
@ambient farm
@theme farm
@zone farm
@flight true
@music farm_theme
# props: object char -> ART id (collision, strips and lights come from lua/config/props.lua + props_extra.lua)
@prop 6 tree_oak_farm
@prop 7 bush_farm
@prop 8 rock_grey
@prop 9 tree_oak_farm_b
@prop F fence_x
@prop G fence_gate_x
@prop L lantern_post
@prop N bench
@prop Q trunk_giant_b
@prop R trunk_giant_a
@prop S scarecrow
@prop Z fence_z
# markers: spawn warp sign bed quest_spot light growth are built in; every other type is resolved by the handler registry
# (a type without a handler script yet is skipped silently and stays readable through area.find_markers(type))
@marker J ambient_fx kind=auto
@marker c animal_yard r=3
@marker B bed
@marker d building_slot type=coop
@marker e building_slot type=barn
@marker f building_slot type=house
@marker z dig_spot
@marker 0 dress season=efteraar prop=leaf_pile
@marker 3 dress season=efteraar prop=pumpkin_stack
@marker 4 dress season=vinter prop=snow_patch
@marker 5 dress event=festival_now prop=bunting_x
@marker M dress tier=3 prop=flower_box
@marker O dress tier=5 prop=garden_arch
@marker P dress tier=8 prop=fountain_small
@marker U dress tier=10 prop=royal_banner
@marker V dress season=foraar prop=blossom_cluster
@marker Y dress season=sommer prop=sunflower_row
@marker x field_expansion id=east cells=40..45,24..30 price=800
@marker l greenhouse_slot
@marker + spawn name=from_greenhouse
@marker g growth stage=1 cells=31..39,12
@marker h growth stage=2 cells=31..39,11
@marker i growth stage=3 cells=31..39,10
@marker H home
@marker m light kind=lantern r=240 h=70
@marker p light kind=lantern r=260 h=60
@marker X mailbox prop=mailbox_red
@marker A node kind=apple_tree
@marker k node kind=tree_chop
@marker o node kind=rock_stone
@marker w node kind=flower_patch
@marker C post name=bench_a facing=SW act=sit
@marker D post name=porch facing=SW act=stand
@marker I post name=field_edge facing=S act=stand
@marker r post name=pip_mailbox facing=SW act=stand
@marker y post name=hoppe_fence facing=E act=stand
@marker q quest_spot quest=lost_cat objective=follow_pawprints prompt=WORLD_PROMPT_USE prop=paw_prints when=quest:lost_cat
@marker K shipping_bin prop=shipping_bin
@marker j sign text=SIGN_FARM_FOREST
@marker n sign text=SIGN_FARM_BRIDGE
@marker s sign text=SIGN_ORCHARD
@marker a spawn name=from_home
@marker b spawn name=from_traetoppen
@marker t tent
@marker E tool_shed prop=tool_shed
@marker T town curfew=false
@marker 1 underdeck prop=trunk_under_a
@marker 2 underdeck prop=trunk_under_b
@marker u unique_spot id=fuglehuset
@marker v unique_spot id=trae_hulning
@marker W warp to=traetoppen spawn=from_farm label=ZONE_TRAETOPPEN
@ground
